/* eslint-disable @typescript-eslint/no-require-imports -- Owned daemon, local webseed, generated bytes. */
const fs=require('node:fs'),path=require('node:path'),http=require('node:http'),crypto=require('node:crypto'),assert=require('node:assert/strict');
const {spawnSync}=require('node:child_process');
const root=path.resolve(__dirname,'..'),output=path.join(root,'artifacts/one-pc-extended-20261106');fs.mkdirSync(output,{recursive:true});
const seconds=Number(process.argv.find(arg=>arg.startsWith('--seconds='))?.slice(10)||3600);
assert.ok(Number.isInteger(seconds)&&seconds>=60&&seconds<=86400);
const reportPath=path.join(output,seconds===3600?'native-hour.json':'native-dry-run.json');
const report={startedAt:new Date().toISOString(),plannedSeconds:seconds,passed:false,samples:[],controls:[],source:'Generated 512MiB file, loopback HTTP webseed, production bundled Transmission; no public tracker or user profile'};
const save=()=>fs.writeFileSync(reportPath,JSON.stringify(report,null,2)),sleep=ms=>new Promise(resolve=>setTimeout(resolve,ms));
const dir=fs.mkdtempSync(path.join(output,'native-soak-')),source=path.join(dir,'sample.bin'),size=512*1024*1024;
async function fileHash(file){const hash=crypto.createHash('sha256');for await(const chunk of fs.createReadStream(file))hash.update(chunk);return hash.digest('hex');}
let sidecar,server;
(async()=>{
  save();const fd=fs.openSync(source,'wx');try{const block=Buffer.alloc(1024*1024,37);for(let i=0;i<512;i++)fs.writeSync(fd,block);}finally{fs.closeSync(fd);}
  const sourceHash=await fileHash(source);
  let requests=0;
  server=http.createServer((req,res)=>{
    if(req.url!=='/sample.bin'){res.writeHead(404);res.end();return;}
    requests++;const range=/bytes=(\d+)-(\d*)/.exec(req.headers.range||''),start=range?Number(range[1]):0,end=range&&range[2]?Number(range[2]):size-1;
    if(start>end||end>=size){res.writeHead(416);res.end();return;}
    res.writeHead(range?206:200,{'Content-Type':'application/octet-stream','Content-Length':end-start+1,'Accept-Ranges':'bytes',...(range?{'Content-Range':`bytes ${start}-${end}/${size}`}:{})});
    if(req.method==='HEAD'){res.end();return;}
    const stream=fs.createReadStream(source,{start,end,highWaterMark:32*1024});
    stream.on('data',chunk=>{stream.pause();if(res.write(chunk))setTimeout(()=>stream.resume(),50);else res.once('drain',()=>setTimeout(()=>stream.resume(),50));});
    stream.on('end',()=>res.end());stream.on('error',()=>res.destroy());res.on('close',()=>stream.destroy());
  });
  await new Promise(resolve=>server.listen(0,'127.0.0.1',resolve));
  const createTorrent=(await import('create-torrent')).default;
  const metainfo=await new Promise((resolve,reject)=>createTorrent(source,{announceList:[],private:true,urlList:[`http://127.0.0.1:${server.address().port}/sample.bin`],pieceLength:256*1024},(error,bytes)=>error?reject(error):resolve(bytes)));
  const {TransmissionSidecar}=require('../dist/electron/electron/torrent/native/transmission-sidecar.js');
  sidecar=new TransmissionSidecar({binaryPath:path.join(root,'vendor/transmission/win32-x64/transmission-daemon.exe'),configDir:path.join(dir,'engine'),downloadDir:path.join(dir,'download'),settingsOverrides:{'dht-enabled':false,'pex-enabled':false,'lpd-enabled':false,'port-forwarding-enabled':false,'speed-limit-down-enabled':true,'speed-limit-down':256}});
  const rpc=await sidecar.start(),added=await rpc.torrentAdd({metainfo:Buffer.from(metainfo).toString('base64')});
  const snapshot=async()=>(await rpc.torrentGet(['status','downloadedEver','percentDone','error','errorString','rateDownload'],added.hashString))[0];
  const startup=Date.now()+60000;while(!(await snapshot()).downloadedEver){report.warmup={...(await snapshot()),requests};save();assert.ok(Date.now()<startup,'Local webseed never started');await sleep(500);}
  const began=Date.now(),end=began+seconds*1000,interval=Math.min(15000,seconds*1000/12),pauseEvery=Math.max(20,seconds/4)*1000;
  let previous=0,lastProgress=began,lastMinute=-1,pausedAt=0,lastCap=256;
  while(Date.now()<end){
    const now=Date.now(),elapsed=now-began,cap=[64,128,64][Math.min(2,Math.floor(elapsed/(seconds*1000/3)))];
    if(cap!==lastCap){await rpc.sessionSet({'speed-limit-down-enabled':true,'speed-limit-down':cap});report.controls.push({elapsedSeconds:elapsed/1000,kind:'rate-limit',kibPerSecond:cap});lastCap=cap;}
    if(Math.floor(elapsed/pauseEvery)>pausedAt&&elapsed<seconds*1000-10000){
      pausedAt=Math.floor(elapsed/pauseEvery);await rpc.torrentStop(added.hashString);await sleep(1200);const stopped=await snapshot();assert.equal(stopped.status,0);
      await rpc.torrentStart(added.hashString);const resumed=Date.now()+10000;while(![3,4].includes((await snapshot()).status)){assert.ok(Date.now()<resumed,'Download did not resume');await sleep(100);}report.controls.push({elapsedSeconds:elapsed/1000,kind:'pause-resume',stopped:true});
    }
    const state=await snapshot();assert.equal(state.error,0,state.errorString);assert.ok(state.status===4||state.status===3,'Download left its running state');
    if(state.downloadedEver>previous){lastProgress=Date.now();previous=state.downloadedEver;}assert.ok(Date.now()-lastProgress<120000,'Download stalled for two minutes');
    const minute=Math.floor(elapsed/60000),sample={elapsedSeconds:elapsed/1000,...state,requests,harnessRssBytes:process.memoryUsage().rss};
    if(minute!==lastMinute){lastMinute=minute;if(sidecar.pid){const memory=spawnSync('powershell.exe',['-NoProfile','-Command',`(Get-Process -Id ${sidecar.pid}).WorkingSet64`],{encoding:'utf8',windowsHide:true});sample.daemonWorkingSetBytes=Number(memory.stdout.trim())||null;}console.log(`MINUTE ${minute}: ${state.downloadedEver} bytes, status=${state.status}, errors=${state.error}`);}
    report.samples.push(sample);save();await sleep(Math.min(interval,Math.max(1,end-Date.now())));
  }
  await rpc.torrentStop(added.hashString);report.elapsedSeconds=(Date.now()-began)/1000;report.final=await snapshot();
  assert.ok(report.elapsedSeconds>=seconds);assert.ok(report.final.downloadedEver>report.samples[0].downloadedEver);assert.ok(report.controls.some(control=>control.kind==='pause-resume'));
  assert.equal(await fileHash(source),sourceHash);report.passed=true;console.log('PASS native soak '+seconds+'s');
})().catch(error=>{report.error=String(error.stack||error);console.error(error);process.exitCode=1;}).finally(async()=>{
  if(sidecar)await sidecar.stop();if(server){server.closeAllConnections();await new Promise(resolve=>server.close(resolve));}
  report.finishedAt=new Date().toISOString();save();
  if(report.passed){assert.equal(path.dirname(dir),output);assert.match(path.basename(dir),/^native-soak-/);fs.rmSync(dir,{recursive:true,force:true});}
});
